<?php require_once __DIR__.'/components.php';$customerId=(int)user()['id']; ?>
<div class="page-heading"><div class="eyebrow">DEIN KUNDENKONTO</div><h1><?= e($title) ?></h1><p><?= e(['quotes'=>'Persönliche Angebote prüfen und bequem mit PayPal bezahlen.','invoices'=>'Deine Rechnungen als PDF, jederzeit abrufbar.','notifications'=>'Angebote, Zahlungen und Bereitstellungen im Überblick.'][$page]) ?></p></div>
<?php if($page==='quotes'):$id=(int)($_GET['id']??0);$q=$id?one("SELECT * FROM shop_quotes WHERE id=? AND customer_id=? AND status<>'draft'",[$id,$customerId]):null; ?>
<?php if($id && !$q):http_response_code(404);empty_state('mail','Angebot nicht verfügbar','Dieses Angebot ist für dein Konto nicht verfügbar.','/konto/angebote','Alle Angebote');elseif($q): ?><a class="back-link" href="/konto/angebote">← Alle Angebote</a><section class="panel form-panel"><?php quote_details($q); ?></section><?php else:$args=[$customerId];$sql="SELECT * FROM shop_quotes WHERE customer_id=? AND status<>'draft'";if(isset($_GET['anfrage'])){$sql.=' AND request_id=?';$args[]=(int)$_GET['anfrage'];}$quotes=all($sql.' ORDER BY id DESC',$args); ?><section class="panel"><?php if(!$quotes):empty_state('mail','Noch kein Angebot verfügbar','Sobald dein persönliches Angebot bereitsteht, bekommst du eine Benachrichtigung und eine E-Mail mit Zahlungslink.','/konto/anfragen','Meine Anfragen');else: ?><div class="table-scroll"><table><thead><tr><th>Angebot</th><th>Preis inkl. MwSt.</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($quotes as $q): ?><tr><td><strong><?= e($q['title']) ?></strong><small>Gültig bis <?= date_de($q['expires_at']) ?></small></td><td><?= money($q['gross_cents']) ?> / <?= cycle($q['billing']) ?></td><td><?= e(quote_status($q)) ?></td><td><a class="button button-outline button-small" href="/konto/angebote?id=<?= (int)$q['id'] ?>">Ansehen <?= icon('arrow') ?></a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section><?php endif ?>
<?php elseif($page==='invoices'):require __DIR__.'/invoices-list.php'; ?>
<?php endif ?>
